// Normalise both entry points into one alert and build Slack Block Kit.
//  - Error Trigger: {execution:{id,url,error,lastNodeExecuted}, workflow:{id,name}}
//  - Called by Workflow: {conversation_id, workflow_name, workflow_id,
//    execution_id, failed_node, error_message}
const j = $input.first().json;
const base = String(j.N8N_EDITOR_BASE_URL || '').replace(/\/+$/, '');

let info;
if (j.execution && typeof j.execution === 'object') {
  const ex = j.execution;
  const err = ex.error || {};
  info = {
    source: 'error_trigger',
    conversation_id: null, // not available to an Error Trigger
    workflow_name: (j.workflow && j.workflow.name) || 'unknown workflow',
    workflow_id: (j.workflow && j.workflow.id) || null,
    execution_id: ex.id || null,
    failed_node: ex.lastNodeExecuted || (err.node && err.node.name) || 'unknown node',
    error_message: [err.message, err.description].filter(Boolean).join(' | ') || 'Unknown error',
    fallback_url: ex.url || null,
  };
} else {
  info = {
    source: 'workflow_call',
    conversation_id: j.conversation_id || null,
    workflow_name: j.workflow_name || 'unknown workflow',
    workflow_id: j.workflow_id || null,
    execution_id: j.execution_id || null,
    failed_node: j.failed_node || 'unknown node',
    error_message: j.error_message || 'Unknown error',
    fallback_url: null,
  };
}

const link = base && info.workflow_id && info.execution_id
  ? `${base}/workflow/${info.workflow_id}/executions/${info.execution_id}`
  : info.fallback_url;

const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const errText = String(info.error_message).replace(/```/g, "'''").slice(0, 2800);

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Hotline failure', emoji: true } },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Workflow*\n${esc(info.workflow_name)}` },
      { type: 'mrkdwn', text: `*Conversation*\n${info.conversation_id ? '`' + esc(info.conversation_id) + '`' : 'unknown'}` },
      { type: 'mrkdwn', text: `*Failed node*\n${esc(info.failed_node)}` },
      { type: 'mrkdwn', text: `*Execution*\n${link ? `<${link}|${esc(info.execution_id || 'open')}>` : esc(info.execution_id || 'unknown')}` },
    ],
  },
  { type: 'section', text: { type: 'mrkdwn', text: '```' + errText + '```' } },
];

const text = `Hotline failure in ${info.workflow_name} at ${info.failed_node}` +
  (info.conversation_id ? ` (conversation ${info.conversation_id})` : '') + `: ${String(info.error_message).slice(0, 200)}`;

return [{
  json: {
    ...info,
    execution_url: link || null,
    last_error: `${info.failed_node}: ${info.error_message}`.slice(0, 1000),
    slack_channel: j.SLACK_ALERT_CHANNEL,
    slack_text: text,
    slack_blocks: { blocks },
  },
}];
